Strange enough it works here without a problem...

Could you please make those changes and try again:

``` java
public void run() throws Exception {
        final LocalAddress addr = new LocalAddress(LOCAL_ID);
        Bootstrap cb = new Bootstrap();
        ServerBootstrap sb = new ServerBootstrap();
        EventLoopGroup serverGroup = new LocalEventLoopGroup();
        EventLoopGroup clientGroup = new LocalEventLoopGroup();
        try {
            sb.group(serverGroup)
                    .channel(LocalServerChannel.class)
                    .handler(new ChannelInitializer<LocalServerChannel>(){
                        @Override
                        public void initChannel(LocalServerChannel ch) throws Exception {
                            ch.pipeline().addLast(new LoggingHandler(LogLevel.INFO));
                        }
                    })
                    .childHandler(new ChannelInitializer<LocalChannel>() {
                        @Override
                        public void initChannel(LocalChannel ch) throws Exception {
                            // comment the next line out for it to work
                            ch.pipeline().addLast(new SnappyFramedDecoder());
                            ch.pipeline().addLast(new StringDecoder());
                            ch.pipeline().addLast(new ChannelInboundMessageHandlerAdapter<String>() {
                                @Override
                                public void messageReceived(ChannelHandlerContext ctx,
                                                            String msg) throws Exception {
                                    System.out.println ("RECEIVED: " + msg);
                                }

                                @Override
                                public void exceptionCaught(ChannelHandlerContext ctx, Throwable cause) {
                                    cause.printStackTrace();
                                }
                            });
                        }
                    });

            cb.group(clientGroup)
                    .channel(LocalChannel.class)
                    .handler(new ChannelInitializer<LocalChannel>() {
                        @Override
                        public void initChannel(LocalChannel ch) throws Exception {
                            ch.pipeline().addLast(new StringEncoder ());
                            // comment the next line out for it to work
                            ch.pipeline().addLast(new SnappyFramedEncoder());
                            ch.pipeline().addLast(new ChannelStateHandlerAdapter() {
                                @Override
                                public void inboundBufferUpdated(ChannelHandlerContext ctx) throws Exception {
                                    ctx.fireInboundBufferUpdated();
                                }

                                @Override
                                public void exceptionCaught(ChannelHandlerContext ctx, Throwable cause) {
                                    cause.printStackTrace();
                                }
                            });
                        }
                    });
            // Start the server.
            sb.bind(addr).sync();

            // Start the client.
            Channel ch = cb.connect(addr).sync().channel();

            ChannelFuture lastWriteFuture = ch.write(TEST_STRING);

            // Wait until all messages are flushed before closing the channel.
            if (lastWriteFuture != null) {
                System.out.println ("Waiting");
                lastWriteFuture.awaitUninterruptibly();
                if (!lastWriteFuture.isSuccess()) {
                    lastWriteFuture.cause().printStackTrace();
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            serverGroup.shutdownGracefully();
            clientGroup.shutdownGracefully();
        }
        System.out.println ("Done");
    }
}
```
